python3 -c "
import json
d=json.load(open('contracts/baseline_evaluation.schema.json'))
print('TITLE:', d.get('title'), '| DESC:', (d.get('description') or '')[:200])
def walk(o,p=''):
    if isinstance(o,dict):
        for k,v in o.items():
            if k in ('replacement','replacements','champion','challenger','promotion') or 'replac' in str(k).lower() or 'promot' in str(k).lower():
                print(p+'/'+k, '->', json.dumps(v)[:400])
            walk(v,p+'/'+k)
    elif isinstance(o,list):
        for i,v in enumerate(o[:5]): walk(v,p+f'[{i}]')
walk(d)
"

